// Code generated by regengo
// Tests and benchmarks for pattern: [a-z]+

var thompsonCharClassRegexp = regexp.MustCompile("[a-z]+")

var thompsonCharClassTestInputs = []string{"example"}

func TestThompsonCharClassMatchString(t *testing.T) {
	for _, input := range thompsonCharClassTestInputs {
		expected := thompsonCharClassRegexp.MatchString(input)
		got := ThompsonCharClass{}.MatchString(input)
		if got != expected {
			t.Errorf("MatchString(%q) = %v, want %v", input, got, expected)
		}
	}
}

func TestThompsonCharClassMatchBytes(t *testing.T) {
	for _, input := range thompsonCharClassTestInputs {
		inputBytes := []byte(input)
		expected := thompsonCharClassRegexp.Match(inputBytes)
		got := ThompsonCharClass{}.MatchBytes(inputBytes)
		if got != expected {
			t.Errorf("MatchBytes(%q) = %v, want %v", input, got, expected)
		}
	}
}

func BenchmarkThompsonCharClass(b *testing.B) {
	inputs := thompsonCharClassTestInputs

	b.Run("Match", func(b *testing.B) {
		for i, input := range inputs {
			input := input
			b.Run(fmt.Sprintf("Input[%d]", i), func(b *testing.B) {
				b.Run("stdlib", func(b *testing.B) {
					b.ReportAllocs()
					for b.Loop() {
						_ = thompsonCharClassRegexp.MatchString(input)
					}
				})
				b.Run("regengo", func(b *testing.B) {
					b.ReportAllocs()
					for b.Loop() {
						_ = ThompsonCharClass{}.MatchString(input)
					}
				})
			})
		}
	})

}
